def gen(rng):
    def fmt(rows):
        return str(len(rows)) + ' ' + str(len(rows[0])) + '\n' + '\n'.join(rows)
    def row(m, p):
        r = ['S' if rng.random() < p else '_' for _ in range(m)]
        if 'S' not in r:
            r[rng.randrange(m)] = 'S'
        return ''.join(r)
    tests = [
        fmt(['S']),
        fmt(['S', 'S', 'S']),
        fmt(['SSSS', 'SSSS']),
        fmt(['S____', '__S__']),
        fmt(['S_______', '____S___']),
        fmt(['S_S_', '_S_S', 'S___']),
        fmt(['_S__', '__S_', '___S', 'S___']),
        fmt(['S' + '_' * 9, '_' * 5 + 'S' + '_' * 4, '_' * 3 + 'S' + '_' * 6]),
    ]
    for _ in range(20):
        n = rng.randint(1, 5)
        m = rng.randint(1, 12)
        tests.append(fmt([row(m, rng.choice([0.1, 0.25, 0.5])) for _ in range(n)]))
    for _ in range(4):
        n = rng.randint(30, 60)
        m = rng.randint(30, 60)
        tests.append(fmt([row(m, 0.05) for _ in range(n)]))
    tests.append(fmt([row(1000, 0.0005) for _ in range(1000)]))
    tests.append(fmt([row(1000, 0.3) for _ in range(1000)]))
    tests.append(fmt([row(999, 0.01) for _ in range(1000)]))
    return tests

